CREATE TABLE "RestaurantSettings" ("id" TEXT NOT NULL DEFAULT 'main',"openTime" TEXT NOT NULL DEFAULT '07:00',"closeTime" TEXT NOT NULL DEFAULT '22:00',"acceptingOrders" BOOLEAN NOT NULL DEFAULT true,"roomChargeEnabled" BOOLEAN NOT NULL DEFAULT true,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "RestaurantSettings_pkey" PRIMARY KEY ("id"));
CREATE TABLE "RestaurantModifierGroup" ("id" TEXT NOT NULL,"name" TEXT NOT NULL,"required" BOOLEAN NOT NULL DEFAULT false,"minSelect" INTEGER NOT NULL DEFAULT 0,"maxSelect" INTEGER NOT NULL DEFAULT 1,"active" BOOLEAN NOT NULL DEFAULT true,CONSTRAINT "RestaurantModifierGroup_pkey" PRIMARY KEY ("id"));
CREATE TABLE "RestaurantModifierOption" ("id" TEXT NOT NULL,"groupId" TEXT NOT NULL,"name" TEXT NOT NULL,"priceCents" INTEGER NOT NULL DEFAULT 0,"active" BOOLEAN NOT NULL DEFAULT true,CONSTRAINT "RestaurantModifierOption_pkey" PRIMARY KEY ("id"));
CREATE TABLE "RestaurantProductModifierGroup" ("productId" TEXT NOT NULL,"groupId" TEXT NOT NULL,CONSTRAINT "RestaurantProductModifierGroup_pkey" PRIMARY KEY ("productId","groupId"));
CREATE TABLE "RestaurantIngredient" ("id" TEXT NOT NULL,"name" TEXT NOT NULL,"unit" TEXT NOT NULL,"stockQty" DOUBLE PRECISION NOT NULL DEFAULT 0,"minStockQty" DOUBLE PRECISION NOT NULL DEFAULT 0,"costPerUnitCents" INTEGER NOT NULL DEFAULT 0,"active" BOOLEAN NOT NULL DEFAULT true,CONSTRAINT "RestaurantIngredient_pkey" PRIMARY KEY ("id")); CREATE INDEX "RestaurantIngredient_active_name_idx" ON "RestaurantIngredient"("active","name");
CREATE TABLE "RestaurantRecipeItem" ("productId" TEXT NOT NULL,"ingredientId" TEXT NOT NULL,"quantity" DOUBLE PRECISION NOT NULL,CONSTRAINT "RestaurantRecipeItem_pkey" PRIMARY KEY ("productId","ingredientId"));
CREATE TABLE "RestaurantIngredientMovement" ("id" TEXT NOT NULL,"ingredientId" TEXT NOT NULL,"type" TEXT NOT NULL,"quantity" DOUBLE PRECISION NOT NULL,"reason" TEXT,"orderId" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "RestaurantIngredientMovement_pkey" PRIMARY KEY ("id")); CREATE INDEX "RestaurantIngredientMovement_ingredientId_createdAt_idx" ON "RestaurantIngredientMovement"("ingredientId","createdAt");
ALTER TABLE "RestaurantModifierOption" ADD CONSTRAINT "RestaurantModifierOption_groupId_fkey" FOREIGN KEY ("groupId") REFERENCES "RestaurantModifierGroup"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "RestaurantProductModifierGroup" ADD CONSTRAINT "RestaurantProductModifierGroup_productId_fkey" FOREIGN KEY ("productId") REFERENCES "RestaurantProduct"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "RestaurantProductModifierGroup" ADD CONSTRAINT "RestaurantProductModifierGroup_groupId_fkey" FOREIGN KEY ("groupId") REFERENCES "RestaurantModifierGroup"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "RestaurantRecipeItem" ADD CONSTRAINT "RestaurantRecipeItem_productId_fkey" FOREIGN KEY ("productId") REFERENCES "RestaurantProduct"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "RestaurantRecipeItem" ADD CONSTRAINT "RestaurantRecipeItem_ingredientId_fkey" FOREIGN KEY ("ingredientId") REFERENCES "RestaurantIngredient"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "RestaurantIngredientMovement" ADD CONSTRAINT "RestaurantIngredientMovement_ingredientId_fkey" FOREIGN KEY ("ingredientId") REFERENCES "RestaurantIngredient"("id") ON DELETE CASCADE ON UPDATE CASCADE;